# DSBA 6171 - Selected documents for chunking experiment

selected = [
    "underwriting_policy_2024_superseded.md",
    "underwriting_policy_2026_superseded.md",
    "underwriting_policy_2026_revised.md",
    "DOC-001-CFPB_AI_Adverse_Action_Circular_2023-03.pdf",
    "loan_approval_escalation_procedure.md"
]

items = _input.all()
payload = items[0].json.to_py()
tree = payload["tree"]

files = []

for entry in tree:
    path = entry["path"]
    filename = path.rsplit("/", 1)[-1]

    if (
        entry["type"] == "blob"
        and path.startswith("data/documents/source/")
        and filename in selected
    ):
        files.append({
            "path": path,
            "sha": entry["sha"]
        })

files.sort(key=lambda x: x["path"])

if len(files) != 5:
    raise ValueError(
        "Expected 5 documents, found " + str(len(files))
    )

return [{
    "json": {
        "files": files,
        "embed": True,
        "chunk_size": 800,
        "chunk_overlap": 100,
        "document_count": len(files)
    }
}]

# Python (Beta/Pyodide) — retain all retrieved evidence unmodified.
# Python Beta supports referencing prior nodes with _(node_name).all().
import json

inputs = [item.json.to_py() for item in _input.all()]
cases = [item.json.to_py() for item in _("Define Retrieval Scenarios").all()]


def read_hits(obj):
    if isinstance(obj, list):
        return obj
    for key in ("results", "hits", "matches", "documents", "chunks", "retrieved", "data"):
        value = obj.get(key)
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            for nested_key in ("results", "hits", "matches", "chunks"):
                nested = value.get(nested_key)
                if isinstance(nested, list):
                    return nested
    raise ValueError("Unrecognized retrieval response keys: " + str(list(obj.keys())))


def first_present(*values):
    for value in values:
        if value is not None:
            return value
    return None


def normalize(hit, index):
    meta = hit.get("metadata_json") or hit.get("metadata") or {}
    if isinstance(meta, str):
        try:
            meta = json.loads(meta)
        except ValueError:
            meta = {"raw_metadata": meta}
    meta = meta if isinstance(meta, dict) else {}
    return {
        "rank": index + 1,
        "chunk_id": first_present(hit.get("chunk_id"), hit.get("id"), meta.get("chunk_id")),
        "doc_id": first_present(hit.get("doc_id"), meta.get("doc_id")),
        "source_path": first_present(hit.get("source_path"), hit.get("source"), meta.get("source_path")),
        "version": str(first_present(hit.get("version"), meta.get("version"), "")),
        "authority_status": first_present(hit.get("authority_status"), meta.get("authority_status")),
        "effective_date": first_present(hit.get("effective_date"), meta.get("effective_date")),
        "end_date": first_present(hit.get("end_date"), meta.get("end_date"), meta.get("expiration_date")),
        "section": first_present(hit.get("section"), meta.get("section")),
        "score": first_present(hit.get("score"), hit.get("similarity"), hit.get("distance")),
        "chunk_text": first_present(hit.get("chunk_text"), hit.get("text"), hit.get("page_content"), hit.get("content")),
        "metadata": meta,
        "raw_hit": hit,
    }

if len(inputs) != len(cases):
    raise ValueError("Retrieval response count differs from scenario count: "
                     + str(len(inputs)) + " vs " + str(len(cases)))

results = []
for index, response in enumerate(inputs):
    scenario = cases[index]
    hits = [normalize(hit, rank) for rank, hit in enumerate(read_hits(response))]
    k = int(scenario.get("top_k", 5))
    results.append({"json": {
        "scenario": scenario.get("scenario"),
        "application_id": scenario.get("application_id"),
        "application_date": scenario.get("application_date"),
        "decision_date": scenario.get("decision_date"),
        "product_code": scenario.get("product_code"),
        "query": scenario.get("query"),
        "expected": scenario.get("expected"),
        "excluded": scenario.get("excluded"),
        "requested_top_k": k,
        "received_count": len(hits),
        "raw_top_k": hits[:k],
        "candidates": hits,
        "raw_response": response,
    }})
return results

# Python (Beta/Pyodide) — point-in-time authority gate before AI context.
# Keep the original 20-candidate pool and 5-item final context unchanged.
import re


def numeric_version(hit):
    raw = str(hit.get("version") or "").strip().lower()
    if hit.get("doc_id") in ("FIN-POL-001", "FIN-PROC-001"):
        for n in (3, 2, 1):
            if re.search(r"(^|\D)" + str(n) + r"(\.0)?($|\D)", raw):
                return n
    return None


def eligible(hit, application_date):
    doc = str(hit.get("doc_id") or "")
    version = numeric_version(hit)
    status = str(hit.get("authority_status") or "").upper()
    start = str(hit.get("effective_date") or "")[:10]
    end = str(hit.get("end_date") or "")[:10]

    if not doc or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start):
        return False, "missing ID or ISO effective_date"
    if application_date < start:
        return False, "not yet effective"
    if end and re.fullmatch(r"\d{4}-\d{2}-\d{2}", end) and application_date > end:
        return False, "expired on application date"

    if doc == "FIN-POL-001":
        required = 1 if application_date < "2026-01-01" else 3
        if version != required:
            return False, "incorrect policy version for application date"
        if required == 3 and status != "CURRENT":
            return False, "v3 not marked CURRENT"
        if required == 1 and status not in ("SUPERSEDED", "CURRENT", "APPROVED"):
            return False, "unknown historical authority"
        if required == 1 and not end:
            return False, "historical policy missing end_date"
        return True, "applicable policy"

    if doc == "FIN-PROC-001":
        if application_date >= "2026-01-01" and version != 2:
            return False, "not approved procedure version"
        if application_date < "2026-01-01" and version != 1:
            return False, "not historical procedure version"
        if status not in ("CURRENT", "APPROVED", "SUPERSEDED"):
            return False, "unverified procedure authority"
        return True, "date-applicable procedure"

    return False, "not selected governing policy or procedure"


results = []
for item in _input.all():
    x = item.json.to_py()
    date = x["application_date"]
    allowed, rejected = [], []
    for hit in x["candidates"]:
        ok, reason = eligible(hit, date)
        if ok:
            allowed.append(hit)
        else:
            rejected.append({
                "rank": hit.get("rank"), "chunk_id": hit.get("chunk_id"),
                "doc_id": hit.get("doc_id"), "reason": reason
            })
    context = allowed[:x["requested_top_k"]]
    output = dict(x)
    output.update({
        "architecture_change": "Temporal + version + authority eligibility gate prior to AI context; oversample 20 candidate hits.",
        "eligible_top_k": context,
        "rejected_candidates": rejected,
        "missing_evidence_warning": (
            "Fewer than Top-K verified eligible hits; human review required."
            if len(context) < x["requested_top_k"] else None
        ),
        "what_reached_ai_context": [
            {key: hit.get(key) for key in
             ("chunk_id", "doc_id", "version", "section", "chunk_text", "source_path")}
            for hit in context
        ],
        "manual_classification_required": True,
    })
    results.append({"json": output})
return results
